drills.starter:
export function cached(fn, { ttl, clock }) {
  // TODO: store values with their load time, and share one in-flight load per key
  return (key) => fn(key);
}

drills.solution:
export function cached(fn, { ttl, clock }) {
  const values = new Map();
  const inflight = new Map();
  return function get(key) {
    const hit = values.get(key);
    if (hit && clock.now() - hit.storedAt < ttl) return Promise.resolve(hit.value);
    const pending = inflight.get(key);
    if (pending) return pending;
    const load = Promise.resolve()
      .then(() => fn(key))
      .then((value) => {
        values.set(key, { value, storedAt: clock.now() });
        return value;
      })
      .finally(() => inflight.delete(key));
    inflight.set(key, load);
    return load;
  };
}

