drills.explanation:
Write first, then delete; and let a read store its row only if no write of that user finished while it was waiting:

```js
async getUser(id) {
  const key = keyOf(id);
  if (cache.has(key)) return cache.get(key);
  const before = version(id);
  const row = await db.get(id);
  if (version(id) === before) cache.set(key, row);   // no write finished meanwhile
  return row;
},
async updateUser(id, patch) {
  await db.update(id, patch);
  finishedWrites.set(id, version(id) + 1);
  cache.delete(keyOf(id));
},
```

The version check and `cache.set` run in the same synchronous step, so no write can slip between them.

The tests catch two plausible-wrong versions. Deleting the key BEFORE the write lets the read that arrives during the write miss, load the not-yet-updated row and cache it after the delete has already happened. Plain write-then-delete passes that test but fails the trap: a read that started before the write and finished after it stores the old row once the delete is over, and it stays for a full TTL.

drills.starter:
export function cacheKey(tenant, user, params) {
  // TODO: an unambiguous encoding of tenant, user and the normalised params
  return 'key';
}

drills.solution:
const normalize = (value) => {
  if (Array.isArray(value)) return value.map(normalize);
  if (value !== null && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value).sort()) {
      if (value[k] !== undefined) out[k] = normalize(value[k]);
    }
    return out;
  }
  return value;
};

export function cacheKey(tenant, user, params) {
  return JSON.stringify([tenant, user, normalize(params)]);
}

